  long maxLat2 = (long) maxLat - Integer.MIN_VALUE;
  int latShift = computeGridShift(minLat2, maxLat2);
  int latBase = latBaseForRange(minLat2, latShift);
  int maxLatDelta = (int) (maxLat2 >>> latShift) - latBase + 1;
  assert maxLatDelta > 0;

  long minLon2 = (long) minLon - Integer.MIN_VALUE;
  long maxLon2 = wrappedMaxLongitude((long) maxLon - Integer.MIN_VALUE, shapeMinLon, shapeMaxLon);
  int lonShift = computeGridShift(minLon2, maxLon2);
  int lonBase = lonBaseForRange(minLon2, lonShift);
  int maxLonDelta = (int) (maxLon2 >>> lonShift) - lonBase + 1;
  assert maxLonDelta > 0;

  byte[] relations =
      fillRelationTable(
