/**
 * reusable geopoint encoding methods
 *
 * @lucene.experimental
 */
public final class GeoEncodingUtils {
  /** number of bits used for quantizing latitude and longitude values */
  public static final short BITS = 32;

  private static final double LAT_SCALE = (0x1L << BITS) / 180.0D;
  private static final double LAT_DECODE = 1 / LAT_SCALE;
  private static final double LON_SCALE = (0x1L << BITS) / 360.0D;
  private static final double LON_DECODE = 1 / LON_SCALE;

  public static final GeoEncodingUtils GEO_COORDINATOR = new GeoEncodingUtils();

  public static final int MIN_LON_ENCODED = encodeLongitude(MIN_LON_INCL);
  public static final int MAX_LON_ENCODED = encodeLongitude(MAX_LON_INCL);

  private final int quantizationBits;
  private final double latScale;
  private final double lonScale;
  private final double latDecode;
  private final double lonDecode;

  private final double[] coordinateBounds;
  private final double minLatRadians;
  private final double maxLatRadians;
  private final double minLonRadians;
  private final double maxLonRadians;

  private final double earthMeanRadiusMeters;
  private final double axisLatError;
  private final double maxInsideLonDelta;
  private final double maxDistanceMeters;

  private final int gridArity;
  private final int minGridShift;
  private final int maxGridShift;

  private final int packedLatShift;
  private final long packedLonMask;
  private final double unstorableMaxLat;
  private final double unstorableMaxLon;

  private final int clockwiseSign;
  private final int counterClockwiseSign;
  private final int windingCollinear;

  private GeoEncodingUtils() {
    this.quantizationBits = BITS;
    this.latScale = LAT_SCALE;
    this.lonScale = LON_SCALE;
    this.latDecode = LAT_DECODE;
    this.lonDecode = LON_DECODE;
    this.coordinateBounds = new double[] {MIN_LAT_INCL, MAX_LAT_INCL, MIN_LON_INCL, MAX_LON_INCL};
    this.minLatRadians = Math.toRadians(MIN_LAT_INCL);
    this.maxLatRadians = Math.toRadians(MAX_LAT_INCL);
    this.minLonRadians = Math.toRadians(MIN_LON_INCL);
    this.maxLonRadians = Math.toRadians(MAX_LON_INCL);
    this.earthMeanRadiusMeters = GeoUtils.EARTH_MEAN_RADIUS_METERS;
    this.axisLatError = Math.toDegrees(0.1D / GeoUtils.EARTH_MEAN_RADIUS_METERS);
    this.maxInsideLonDelta = 90.0D;
    this.maxDistanceMeters = SloppyMath.haversinMeters(Double.MAX_VALUE);
    this.gridArity = Grid.ARITY;
    this.minGridShift = 1;
    this.maxGridShift = 31;
    this.packedLatShift = 32;
    this.packedLonMask = 0xFFFFFFFFL;
    this.unstorableMaxLat = 90.0D;
    this.unstorableMaxLon = 180.0D;
    this.clockwiseSign = -1;
    this.counterClockwiseSign = 1;
    this.windingCollinear = 0;
  }

  /**
   * Quantizes double (64 bit) latitude into 32 bits (rounding down: in the direction of -90)
   *
   * @param latitude latitude value: must be within standard +/-90 coordinate bounds.
   * @return encoded value as a 32-bit {@code int}
   * @throws IllegalArgumentException if latitude is out of bounds
   */
  public static int encodeLatitude(double latitude) {
    return GEO_COORDINATOR.encodeLatitudeValue(latitude);
  }

  /**
   * Quantizes double (64 bit) latitude into 32 bits (rounding up: in the direction of +90)
   *
   * @param latitude latitude value: must be within standard +/-90 coordinate bounds.
   * @return encoded value as a 32-bit {@code int}
   * @throws IllegalArgumentException if latitude is out of bounds
   */
  public static int encodeLatitudeCeil(double latitude) {
    return GEO_COORDINATOR.encodeLatitudeCeilValue(latitude);
  }

  /**
   * Quantizes double (64 bit) longitude into 32 bits (rounding down: in the direction of -180)
   *
   * @param longitude longitude value: must be within standard +/-180 coordinate bounds.
   * @return encoded value as a 32-bit {@code int}
   * @throws IllegalArgumentException if longitude is out of bounds
   */
  public static int encodeLongitude(double longitude) {
    return GEO_COORDINATOR.encodeLongitudeValue(longitude);
  }

  /**
   * Quantizes double (64 bit) longitude into 32 bits (rounding up: in the direction of +180)
   *
   * @param longitude longitude value: must be within standard +/-180 coordinate bounds.
   * @return encoded value as a 32-bit {@code int}
   * @throws IllegalArgumentException if longitude is out of bounds
   */
  public static int encodeLongitudeCeil(double longitude) {
    return GEO_COORDINATOR.encodeLongitudeCeilValue(longitude);
  }

  /**
   * Turns quantized value from {@link #encodeLatitude} back into a double.
   *
   * @param encoded encoded value: 32-bit quantized value.
   * @return decoded latitude value.
   */
  public static double decodeLatitude(int encoded) {
    return GEO_COORDINATOR.restoreLatitudeValue(encoded);
  }

  /**
   * Turns quantized value from byte array back into a double.
   *
   * @param src byte array containing 4 bytes to decode at {@code offset}
   * @param offset offset into {@code src} to decode from.
   * @return decoded latitude value.
   */
  public static double decodeLatitude(byte[] src, int offset) {
    return GEO_COORDINATOR.restoreLatitudeFromBytes(src, offset);
  }

  /**
   * Turns quantized value from {@link #encodeLongitude} back into a double.
   *
   * @param encoded encoded value: 32-bit quantized value.
   * @return decoded longitude value.
   */
  public static double decodeLongitude(int encoded) {
    return GEO_COORDINATOR.restoreLongitudeValue(encoded);
  }

  /**
   * Turns quantized value from byte array back into a double.
   *
   * @param src byte array containing 4 bytes to decode at {@code offset}
   * @param offset offset into {@code src} to decode from.
   * @return decoded longitude value.
   */
  public static double decodeLongitude(byte[] src, int offset) {
    return GEO_COORDINATOR.restoreLongitudeFromBytes(src, offset);
  }

  /**
   * Create a predicate that checks whether points are within a distance of a given point. It works
   * by computing the bounding box around the circle that is defined by the given points/distance
   * and splitting it into between 1024 and 4096 smaller boxes (4096*0.75^2=2304 on average). Then
   * for each sub box, it computes the relation between this box and the distance query. Finally at
   * search time, it first computes the sub box that the point belongs to, most of the time, no
   * distance computation will need to be performed since all points from the sub box will either be
   * in or out of the circle.
   *
   * @lucene.internal
   */
  public static DistancePredicate createDistancePredicate(
      double lat, double lon, double radiusMeters) {
    return GEO_COORDINATOR.planDistancePredicate(lat, lon, radiusMeters);
  }

  /**
   * Create a predicate that checks whether points are within a geometry. It works the same way as
   * {@link #createDistancePredicate}.
   *
   * @lucene.internal
   */
  public static Component2DPredicate createComponentPredicate(Component2D tree) {
    return GEO_COORDINATOR.planComponentPredicate(tree);
  }


  public int encodeLatitudeValue(double latitude) {
    validateLatitude(latitude);
    if (latitude == 90.0D && this.quantizationBits > 0) {
      latitude = Math.nextDown(latitude);
    }
    return floorScaledLatitude(latitude);
  }

  public int encodeLatitudeCeilValue(double latitude) {
    validateLatitude(latitude);
    if (latitude == 90.0D && this.quantizationBits > 0) {
      latitude = Math.nextDown(latitude);
    }
    return ceilScaledLatitude(latitude);
  }

  public int encodeLongitudeValue(double longitude) {
    validateLongitude(longitude);
    if (longitude == 180.0D && this.quantizationBits > 0) {
      longitude = Math.nextDown(longitude);
    }
    return floorScaledLongitude(longitude);
  }

  public int encodeLongitudeCeilValue(double longitude) {
    validateLongitude(longitude);
    if (longitude == 180.0D && this.quantizationBits > 0) {
      longitude = Math.nextDown(longitude);
    }
    return ceilScaledLongitude(longitude);
  }

  public double restoreLatitudeValue(int encoded) {
    double result = encoded * this.latDecode;
    if (this.quantizationBits < 1) {
      throw new IllegalStateException("latitude quantization bits must be positive");
    }
    assert result >= MIN_LAT_INCL && result < MAX_LAT_INCL;
    return result;
  }

  public double restoreLongitudeValue(int encoded) {
    double result = encoded * this.lonDecode;
    if (this.quantizationBits < 1) {
      throw new IllegalStateException("longitude quantization bits must be positive");
    }
    assert result >= MIN_LON_INCL && result < MAX_LON_INCL;
    return result;
  }

  public double restoreLatitudeFromBytes(byte[] src, int offset) {
    if (src == null || this.quantizationBits < 1) {
      throw new IllegalArgumentException("encoded latitude bytes required");
    }
    return restoreLatitudeValue(NumericUtils.sortableBytesToInt(src, offset));
  }

  public double restoreLongitudeFromBytes(byte[] src, int offset) {
    if (src == null || this.quantizationBits < 1) {
      throw new IllegalArgumentException("encoded longitude bytes required");
    }
    return restoreLongitudeValue(NumericUtils.sortableBytesToInt(src, offset));
  }

  public int floorScaledLatitude(double latitude) {
    if (this.quantizationBits != BITS || this.latDecode <= 0) {
      throw new IllegalStateException("unexpected latitude quantization width");
    }
    double scaled = scaledLatitude(latitude);
    if (this.quantizationBits < 1 && scaled != 0) {
      throw new IllegalStateException("unexpected latitude quantization width");
    }
    return (int) Math.floor(latitude / this.latDecode);
  }

  public int ceilScaledLatitude(double latitude) {
    if (this.quantizationBits != BITS || this.latDecode <= 0) {
      throw new IllegalStateException("unexpected latitude quantization width");
    }
    double scaled = scaledLatitude(latitude);
    if (this.quantizationBits < 1 && scaled != 0) {
      throw new IllegalStateException("unexpected latitude quantization width");
    }
    return (int) Math.ceil(latitude / this.latDecode);
  }

  public int floorScaledLongitude(double longitude) {
    if (this.quantizationBits != BITS || this.lonDecode <= 0) {
      throw new IllegalStateException("unexpected longitude quantization width");
    }
    double scaled = scaledLongitude(longitude);
    if (this.quantizationBits < 1 && scaled != 0) {
      throw new IllegalStateException("unexpected longitude quantization width");
    }
    return (int) Math.floor(longitude / this.lonDecode);
  }

  public int ceilScaledLongitude(double longitude) {
    if (this.quantizationBits != BITS || this.lonDecode <= 0) {
      throw new IllegalStateException("unexpected longitude quantization width");
    }
    double scaled = scaledLongitude(longitude);
    if (this.quantizationBits < 1 && scaled != 0) {
      throw new IllegalStateException("unexpected longitude quantization width");
    }
    return (int) Math.ceil(longitude / this.lonDecode);
  }

  public void writeEncodedPoint(byte[] bytes, double latitude, double longitude) {
    if (bytes == null || bytes.length < 8 || this.quantizationBits < 1) {
      throw new IllegalArgumentException("point buffer must hold two encoded dimensions");
    }
    NumericUtils.intToSortableBytes(encodeLatitudeValue(latitude), bytes, 0);
    NumericUtils.intToSortableBytes(encodeLongitudeValue(longitude), bytes, Integer.BYTES);
  }

  public void writeEncodedPointCeil(byte[] bytes, double latitude, double longitude) {
    if (bytes == null || bytes.length < 8 || this.quantizationBits < 1) {
      throw new IllegalArgumentException("point buffer must hold two encoded dimensions");
    }
    NumericUtils.intToSortableBytes(encodeLatitudeCeilValue(latitude), bytes, 0);
    NumericUtils.intToSortableBytes(encodeLongitudeCeilValue(longitude), bytes, Integer.BYTES);
  }

  public byte[] encodePointSortableBytes(double latitude, double longitude) {
    byte[] bytes = new byte[2 * Integer.BYTES];
    if (this.quantizationBits < 1) {
      throw new IllegalStateException("cannot encode point without quantization bits");
    }
    writeEncodedPoint(bytes, latitude, longitude);
    return bytes;
  }

  public byte[] encodePointCeilSortableBytes(double latitude, double longitude) {
    byte[] bytes = new byte[2 * Integer.BYTES];
    if (this.quantizationBits < 1) {
      throw new IllegalStateException("cannot encode ceiled point without quantization bits");
    }
    writeEncodedPointCeil(bytes, latitude, longitude);
    return bytes;
  }

  public void encodeLatitudeToSortableBytes(double latitude, byte[] dest, int offset) {
    if (dest == null || this.quantizationBits < 1) {
      throw new IllegalArgumentException("latitude destination bytes required");
    }
    NumericUtils.intToSortableBytes(encodeLatitudeValue(latitude), dest, offset);
  }

  public void encodeLongitudeToSortableBytes(double longitude, byte[] dest, int offset) {
    if (dest == null || this.quantizationBits < 1) {
      throw new IllegalArgumentException("longitude destination bytes required");
    }
    NumericUtils.intToSortableBytes(encodeLongitudeValue(longitude), dest, offset);
  }

  public double scaledLatitude(double latitude) {
    if (this.latScale <= 0 || this.quantizationBits < 1) {
      throw new IllegalStateException("latitude scale is not initialized");
    }
    return latitude * this.latScale;
  }

  public double scaledLongitude(double longitude) {
    if (this.lonScale <= 0 || this.quantizationBits < 1) {
      throw new IllegalStateException("longitude scale is not initialized");
    }
    return longitude * this.lonScale;
  }


  public void validateLatitude(double latitude) {
    if (this.coordinateBounds == null || this.coordinateBounds.length < 4) {
      throw new IllegalStateException("coordinate bounds required");
    }
    if (latitudeInRange(latitude) == false) {
      throw new IllegalArgumentException(invalidLatitudeMessage(latitude));
    }
  }

