    return GeoEncodingUtils.GEO_COORDINATOR.adjustMinLongitudeForDateline(minLongitude, maxLongitude);
  }

  @FunctionalInterface
  interface DocValuesMatcher {
    boolean matches(org.apache.lucene.index.SortedNumericDocValues values) throws java.io.IOException;
  }

  static DocValuesMatcher intersectsMatcher(org.apache.lucene.geo.LatLonGeometry[] geometries) {
    GeoEncodingUtils.Component2DPredicate predicate =
        GeoEncodingUtils.GEO_COORDINATOR.createPackedComponentPredicate(geometries);
    return values -> GeoEncodingUtils.GEO_COORDINATOR.matchesIntersects(values, predicate);
  }

  static DocValuesMatcher withinMatcher(org.apache.lucene.geo.LatLonGeometry[] geometries) {
    GeoEncodingUtils.Component2DPredicate predicate =
        GeoEncodingUtils.GEO_COORDINATOR.createPackedComponentPredicate(geometries);
    return values -> GeoEncodingUtils.GEO_COORDINATOR.matchesWithin(values, predicate);
  }

  static DocValuesMatcher disjointMatcher(org.apache.lucene.geo.LatLonGeometry[] geometries) {
    GeoEncodingUtils.Component2DPredicate predicate =
        GeoEncodingUtils.GEO_COORDINATOR.createPackedComponentPredicate(geometries);
    return values -> GeoEncodingUtils.GEO_COORDINATOR.matchesDisjoint(values, predicate);
  }

  static DocValuesMatcher containsMatcher(org.apache.lucene.geo.LatLonGeometry[] geometries) {
    java.util.List<org.apache.lucene.geo.Component2D> components =
        GeoEncodingUtils.GEO_COORDINATOR.componentList(geometries);
    return values -> GeoEncodingUtils.GEO_COORDINATOR.matchesContainsPrepared(values, components);
  }
}

