import java.lang.reflect.Field;
import org.apache.lucene.geo.Component2D;
import org.apache.lucene.geo.GeoEncodingUtils;
import org.apache.lucene.geo.LatLonGeometry;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.index.PointValues.Relation;

public class Debug {
  public static void main(String[] args) throws Exception {
    int base = Integer.MAX_VALUE;
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    Polygon poly =
        new Polygon(
            new double[] {minLat, minLat, maxLat, maxLat, minLat},
            new double[] {minLon, maxLon, maxLon, minLon, minLon});
    Component2D tree = LatLonGeometry.create(poly);

    GeoEncodingUtils.GeoCoordinatorLike noop = null; // placeholder
    var coord = GeoEncodingUtils.GEO_COORDINATOR;
    int eMinLat = coord.encodedMinLatitude(poly.minLat);
    int eMaxLat = coord.encodedMaxLatitude(poly.maxLat);
    int eMinLon = coord.encodedMinLongitude(poly.minLon);
    int eMaxLon = coord.encodedMaxLongitude(poly.maxLon);
    System.out.println("encoded lat range: " + (eMinLat - (long) Integer.MIN_VALUE) + " .. "
        + (eMaxLat - (long) Integer.MIN_VALUE));
    System.out.println("encoded lon range: " + (eMinLon - (long) Integer.MIN_VALUE) + " .. "
        + (eMaxLon - (long) Integer.MIN_VALUE));

    GeoEncodingUtils.Component2DPredicate pred =
        coord.createPackedComponentPredicate(new LatLonGeometry[] {poly});

    Class<?> c = pred.getClass().getSuperclass();
    for (String f : new String[] {"latShift", "lonShift", "latBase", "lonBase", "maxLatDelta", "maxLonDelta"}) {
      Field field = c.getDeclaredField(f);
      field.setAccessible(true);
      System.out.println(f + " = " + field.get(pred));
    }
    Field relF = c.getDeclaredField("relations");
    relF.setAccessible(true);
    byte[] relations = (byte[]) relF.get(pred);
    System.out.println("relations = " + java.util.Arrays.toString(relations));
    System.out.println("ordinals: INSIDE=" + Relation.CELL_INSIDE_QUERY.ordinal()
        + " CROSSES=" + Relation.CELL_CROSSES_QUERY.ordinal()
        + " OUTSIDE=" + Relation.CELL_OUTSIDE_QUERY.ordinal());

    int lat = base - 2, lon = base - 2;
    int latShift = getField(c, pred, "latShift");
    int lonShift = getField(c, pred, "lonShift");
    int latBase = getField(c, pred, "latBase");
    int lonBase = getField(c, pred, "lonBase");
    int maxLatDelta = getField(c, pred, "maxLatDelta");
    int maxLonDelta = getField(c, pred, "maxLonDelta");
    int lat2 = ((lat - Integer.MIN_VALUE) >>> latShift);
    int lon2 = ((lon - Integer.MIN_VALUE) >>> lonShift);
    System.out.println("lat2=" + (lat2 & 0xFFFFFFFFL) + " latBase=" + (latBase & 0xFFFFFFFFL)
        + " lat2-latBase=" + (lat2 - latBase));
    System.out.println("lon2=" + (lon2 & 0xFFFFFFFFL) + " lonBase=" + (lonBase & 0xFFFFFFFFL)
        + " lon2-lonBase=" + (lon2 - lonBase));
    if (lat2 >= latBase && lat2 < latBase + maxLatDelta && lon2 - lonBase >= 0
        && lon2 - lonBase < maxLonDelta) {
      int rel = relations[(lat2 - latBase) * maxLonDelta + (lon2 - lonBase)];
      System.out.println("cell relation = " + rel);
    } else {
      System.out.println("point outside grid!");
    }
    System.out.println("tree.contains decoded point: "
        + tree.contains(GeoEncodingUtils.decodeLongitude(lon), GeoEncodingUtils.decodeLatitude(lat)));
    System.out.println("pred.test: " + pred.test(lat, lon));
  }

  static int getField(Class<?> c, Object o, String name) throws Exception {
    Field f = c.getDeclaredField(name);
    f.setAccessible(true);
    return f.getInt(o);
  }
}

