package org.apache.lucene.document;

import org.apache.lucene.geo.GeoEncodingUtils;
import org.apache.lucene.geo.LatLonGeometry;
import org.apache.lucene.geo.Polygon;

public class Debug2 {
  public static void main(String[] a) {
    int base = Integer.MAX_VALUE;
    double pLat = GeoEncodingUtils.decodeLatitude(base - 2);
    double pLon = GeoEncodingUtils.decodeLongitude(base - 2);
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    Polygon poly =
        new Polygon(
            new double[] {minLat, minLat, maxLat, maxLat, minLat},
            new double[] {minLon, maxLon, maxLon, minLon, minLon});
    GeoEncodingUtils.Component2DPredicate pred =
        GeoEncodingUtils.GEO_COORDINATOR.createPackedComponentPredicate(
            new LatLonGeometry[] {poly});
    long packed = LatLonPoint.packEncodedLocation(pLat, pLon);
    int elat = GeoEncodingUtils.GEO_COORDINATOR.unpackEncodedLatitude(packed);
    int elon = GeoEncodingUtils.GEO_COORDINATOR.unpackEncodedLongitude(packed);
    System.out.println(
        "encoded point lat="
            + (elat - (long) Integer.MIN_VALUE)
            + " lon="
            + (elon - (long) Integer.MIN_VALUE));
    System.out.println("pred.test(elat, elon): " + pred.test(elat, elon));
    System.out.println("pred.test(base-2, base-2): " + pred.test(base - 2, base - 2));
    System.out.println(
        "matchesIntersects simulated: "
            + GeoEncodingUtils.GEO_COORDINATOR.packedPointInComponent(packed, pred));
  }
}

